def make_legacy_cases(library):
    cases=[]
    def add(mid,step,text,expected,kind):
        cases.append(dict(mission_id=mid,step_id=step,text_sv=text,expected_intent=expected,kind=kind))
    for sit in library['situations']:
        for m in sit['missions']:
            key=m['id'][4:]; steps={s['id']:s for s in m['steps']}
            add(m['id'],'request',REQUESTS[key],'request_answer','natural_request')
            if key=='course_planning_m2':
                cases[-1]['expected_intent']=None;cases[-1]['kind']='different_goal_request'
                add(m['id'],'request','Jag skulle vilja öva på hur man ställer frågor.','request_answer','natural_request')
            if key=='social_plans_m3':
                cases[-1]['expected_intent']=None;cases[-1]['kind']='different_goal_request'
                add(m['id'],'request','Kan vi prata om hur vi delar på utgifterna för festen?','request_answer','natural_request')
            for i,text in enumerate(DETAILS.get(key,[]),1):add(m['id'],f'detail_{i}',text,f'detail_{i}_answer','natural_detail')
            for intent,variants in zip(steps['choice']['intents'],CHOICES[key]):
                for text in variants:add(m['id'],'choice',text,intent['id'],'natural_choice')
                # A rejection followed by the offered option is not an acceptance.
                add(m['id'],'choice','Nej, '+variants[0].rstrip('.'),'NO_MATCH','negated_choice')
            add(m['id'],'choice',DISTRACTORS[sit['id'][4:]][int(key[-1])-1],'NO_MATCH','nearby_topic_choice')
            a,b=CHOICES[key]
            add(m['id'],'choice',a[0]+' Eller '+b[0],'NO_MATCH','ambiguous_choice')
            for step in (s for s in m['steps'] if s['id'].startswith('confirm_')):
                for text in ['Ja tack.','Absolut, det passar.','Det fungerar fint.','Gärna.']:add(m['id'],step['id'],text,'confirm','natural_confirmation')
                for text in ['Nej tack.','Det passar tyvärr inte.','Jag vill helst inte.']:add(m['id'],step['id'],text,'decline','natural_decline')
                for text in ['Ja, men nej.','Nej, men ja.','Ja, det passar inte.','Bananerna går till skolan.']:add(m['id'],step['id'],text,'NO_MATCH','unsafe_confirmation')
    for c in cases:
        if c['expected_intent']=='NO_MATCH':c['expected_intent']=None
    return {'schema_version':'2.0','authored_against':'2026-11-01.2','status':'Authored before repairs, then retained as transparent regression evidence. Includes ordinary phrases, paraphrases, elliptical choices, inflections, negation, ambiguity and nearby-topic distractors. Not an external learner sample.','annotation_corrections':['Review found two valid Swedish requests address a different goal: understanding speech instead of practising questions; total party budget instead of splitting costs. Preserved them as different-goal negatives and added two appropriate positives. Initial corpus and results remain in snapshots.'],'cases':cases}

if __name__=='__main__':
    baseline=json.loads((ROOT/'snapshots/library-2026-11-01.2.json').read_text(encoding='utf-8'))
    # Preserve the historical generator for reproducibility, but never publish its
    # synthetic labels as fresh gold or overwrite the frozen original artifact.
    from adjudicate_natural_controls import publish
    publish(make_legacy_cases(baseline))
